    while True:
        for m in range(1, 13):
            if month is not None and m != month:
                continue
            if m < now.month and y == now.year:
                continue
            d_start = 1 if (m > now.month or y > now.year) else now.day
            d_end = calendar.monthrange(y, m)[1]
            for d in range(d_start, d_end + 1):
                if day is not None and d != day:
                    continue
                for h in range(24):
                    if hour is not None and h != hour:
                        continue
                    if d == now.day and m == now.month and y == now.year and h < now.hour:
                        continue
                    for mi in range(60):
                        if minute is not None and mi != minute:
                            continue
                        if d == now.day and m == now.month and y == now.year and h == now.hour and mi < now.minute:
                            continue
                        dt = datetime(y, m, d, h, mi)
                        if dow is not None and dt.weekday() != dow:
                            continue
                        return dt
        y += 1

