import re

def harden_ssh_config(config_path: str) -> dict:
    recommendations = {
        "PermitRootLogin": "no",
        "PasswordAuthentication": "no",
        "Protocol": "2",
        "MaxAuthTries": "3",
        "X11Forwarding": "no",
        "PermitEmptyPasswords": "no"
    }
    try:
        with open(config_path, 'r') as f:
            content = f.read()
    except FileNotFoundError:
        return {"error": "Config file not found"}

    for key, secure_val in recommendations.items():
        pattern = re.compile(rf"^\s*{re.escape(key)}\s+(.+)", re.IGNORECASE | re.MULTILINE)
        match = pattern.search(content)
        if not match:
            recommendations[key] = f"Saknas (Rekommenderas: {secure_val})"
        elif match.group(1).strip() != secure_val:
            recommendations[key] = f"Nuvarande: {match.group(1).strip()} (Rekommenderas: {secure_val})"
        else:
            del recommendations[key]

    return recommendations
